(()=>{let latest=null,timer=null,requesting=false;function modal(){document.querySelector('#filmPreviewModal')?.remove();const d=document.createElement('dialog');d.id='filmPreviewModal';d.style.cssText='width:min(960px,92vw);max-height:90vh;overflow:auto;background:#182331;color:#e5edf4;border:1px solid #465464;border-radius:16px;padding:24px';d.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center"><h3>成片预览</h3><button data-close>关闭</button></div><p class="subtle">较小尺寸预览，包含当前音量、已采用音轨、字幕和转场。修改设置后请重新预览。</p><p data-status>正在准备预览…</p><video controls playsinline preload="metadata" hidden style="width:100%;max-height:65vh;background:#080d14"></video>';document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>{clearTimeout(timer);d.querySelector('video').pause();});d.showModal();return d;}async function watch(d,j){latest=j;if(!d.open)return;const label=d.querySelector('[data-status]');label.textContent=j.status==='failed'?'预览失败：'+j.error:j.status==='completed'?'预览已就绪':(j.phase||'正在生成预览')+' · '+(j.progress||0)+'%';if(j.status==='completed'){const v=d.querySelector('video');v.hidden=false;v.src=j.video_url;return;}if(j.status==='failed')return;timer=setTimeout(async()=>{try{await watch(d,await frontFetch('/api/film-export/'+j.id));}catch(e){label.textContent='读取预览失败：'+e.message;}},1500);}function draw(){if(tab!==5)return;const anchor=document.querySelector('[data-film-start="full"]');if(!anchor||document.querySelector('#filmPreviewStart'))return;const b=document.createElement('button');b.id='filmPreviewStart';b.textContent='预览成片';b.style.marginRight='10px';anchor.before(b);b.onclick=async()=>{if(requesting)return;const d=modal();if(latest&&latest.project_id===data.project_id&&['queued','running'].includes(latest.status))return watch(d,latest);requesting=true;b.disabled=true;try{await flushDisk();if(diskConflict||lastDiskData!==JSON.stringify(data))throw Error('项目尚未保存，请先处理保存提示');const all=filmItems(),chosen=all.filter(x=>x.video?.video_url);if(!chosen.length)throw Error('请先生成至少一个分镜视频');const j=await frontFetch('/api/film-export',{preview:true,project_id:data.project_id,title:data.title,partial:chosen.length!==all.length,subtitles:true,audio_selections:Object.fromEntries(chosen.map(x=>[x.target.shot_id||x.target.id,x.target.audioProduction||{}])),items:chosen.map(x=>({target_id:x.target.shot_id||x.target.id,video_id:x.video.id||x.video.job_id}))});await watch(d,j);}catch(e){d.querySelector('[data-status]').textContent=e.message;}finally{requesting=false;b.disabled=false;}};}const previous=stage;stage=function(){previous();draw();};render();})();